def test_r4_handles_multiple_clients():
    """Several clients can be served during one run (non-blocking server)."""
    port = _free_port()
    results = []
    t = _run_server_in_thread(port, 4, results=results)
    payloads = [b"client-one", b"client-two", b"client-three"]
    replies = {}
    try:
        socks = [_connect_with_retry(port) for _ in payloads]
        try:
            for sock, payload in zip(socks, payloads):
                sock.sendall(payload)
            for idx, (sock, payload) in enumerate(zip(socks, payloads)):
                replies[idx] = _recv_until(sock, lambda d: len(d) > len(payload))
        finally:
            for sock in socks:
                sock.close()
    finally:
        t.join(timeout=20)

    assert not t.is_alive(), "task_func did not return"
    for idx, payload in enumerate(payloads):
        text = replies[idx].decode("utf-8", errors="replace")
        assert payload.decode() in text, (
            f"client {idx} did not get its own data echoed: {text!r}"
        )

