def test_r7_custom_buffer_size_still_echoes():
    """A custom buffer_size is honoured and data is still echoed with a time."""
    port = _free_port()
    results = []
    t = _run_server_in_thread(port, 3, buffer_size=16, results=results)
    payload = b"abc"
    before = datetime.now() - timedelta(seconds=2)
    try:
        sock = _connect_with_retry(port)
        try:
            sock.sendall(payload)
            data = _recv_until(sock, lambda d: len(d) > len(payload))
        finally:
            sock.close()
    finally:
        t.join(timeout=20)
    after = datetime.now() + timedelta(seconds=2)

    text = data.decode("utf-8", errors="replace")
    assert "abc" in text, f"data not echoed with small buffer: {text!r}"
    assert any(ch.isdigit() for ch in text), f"no time appended: {text!r}"
    assert before.year <= after.year

