def test_r4_custom_port_and_buffer_size(free_port):
    results = {}

    def run():
        try:
            results["return"] = task_func(
                server_address="localhost",
                server_port=free_port,
                buffer_size=16,
                run_duration=3,
            )
        except BaseException as exc:  # pragma: no cover
            results["error"] = exc

    thread = threading.Thread(target=run, daemon=True)
    thread.start()

    deadline = time.monotonic() + 5
    sock = None
    while time.monotonic() < deadline and sock is None:
        try:
            sock = socket.create_connection(("localhost", free_port), timeout=1.0)
        except OSError:
            time.sleep(0.05)
    assert sock is not None, "server did not listen on the requested port"
    sock.settimeout(3.0)
    try:
        sock.sendall(b"ping")
        data = b""
        end = time.monotonic() + 3
        while len(data) < 5 and time.monotonic() < end:
            try:
                chunk = sock.recv(4096)
            except socket.timeout:
                break
            if not chunk:
                break
            data += chunk
    finally:
        sock.close()
    thread.join(timeout=20)

    assert "error" not in results, results.get("error")
    assert data.startswith(b"ping"), data
    assert len(data) > 4

def _free_port():
    """Pick a currently unused localhost TCP port."""
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        s.bind(("localhost", 0))
        return s.getsockname()[1]
    finally:
        s.close()

def _run_in_thread(**kwargs):
    """Start task_func in a background thread; return (thread, result_box)."""
    box = {}

    def runner():
        try:
            box["result"] = task_func(**kwargs)
        except BaseException as exc:  # noqa: BLE001 - surfaced by the test
            box["error"] = exc

    thread = threading.Thread(target=runner, daemon=True)
    thread.start()
    return thread, box

def _connect(port, timeout=5.0):
    """Connect to the server, retrying while it is still starting up."""
    deadline = time.time() + timeout
    last_error = None
    while time.time() < deadline:
        try:
            return socket.create_connection(("localhost", port), timeout=2.0)
        except OSError as exc:  # server not listening yet
            last_error = exc
            time.sleep(0.05)
    raise AssertionError(f"could not connect to server on port {port}: {last_error}")

def _recv_all(sock, timeout=3.0):
    """Read everything the server sends until it closes or goes quiet."""
    sock.settimeout(timeout)
    chunks = []
    while True:
        try:
            data = sock.recv(4096)
        except socket.timeout:
            break
        if not data:
            break
        chunks.append(data)
    return b"".join(chunks)

def test_r5_multiple_clients_served():
    """Several clients are served concurrently by the non-blocking server."""
    port = _free_port()
    thread, box = _run_in_thread(server_port=port, run_duration=5)
    try:
        clients = [_connect(port) for _ in range(3)]
        try:
            for index, client in enumerate(clients):
                client.sendall(f"client-{index}".encode())
            for index, client in enumerate(clients):
                echoed = _recv_all(client)
                assert f"client-{index}".encode() in echoed, (
                    f"client {index} did not get its own data back: {echoed!r}"
                )
        finally:
            for client in clients:
                client.close()
    finally:
        thread.join(timeout=20)
    assert "error" not in box, f"task_func raised: {box.get('error')!r}"
